<script module lang="ts">
/**
 * The action primitive (`design/components/button.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/button.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy } from 'svelte'

import {
  Icon,
  agentMember,
  agentPress,
  chainHandlers,
  joinSlot,
  watchEffect,
  type IconRole,
  type LawfulVariants,
} from '@polymorph/svelte'
import styles from '@polymorph/recipes/controls/button.module.css'
import Badge from '../structure/Badge.svelte'

export interface ButtonGrid {
  solid: 'accent' | 'danger'
  soft: 'accent' | 'danger'
  outline: 'neutral' | 'accent' | 'danger'
  ghost: 'neutral' | 'accent' | 'danger'
}

export type ButtonAppearance = LawfulVariants<ButtonGrid>

export interface ButtonCount {
  value: number
  label: string
}

export interface ButtonProps {
  /**
   * The id of the region the button shows and hides. Set it only while the region is in the
   * document, because an id that names nothing is a broken reference.
   */
  'aria-controls'?: string
  /**
   * Associates supporting status or help copy with the action.
   */
  'aria-describedby'?: string
  /**
   * Overrides the visible label as the accessible action name when context must be explicit.
   */
  'aria-label'?: string
  /**
   * The id of a label elsewhere that names the button, as when `SettingsRow` labels a whole row.
   * `label` is still the visible text. This prop sets the accessible name.
   */
  'aria-labelledby'?: string
  /**
   * A count on the button's corner, with the name that says it. Above zero, the count shows as a
   * Badge and `count.label` is the accessible name. At zero, neither shows and `label` names the
   * button.
   */
  count?: ButtonCount
  /**
   * Marks the button as the current location with `aria-current="page"`. It sets one attribute
   * and changes no styling. Pagination uses it, because its current page is a `soft/accent`
   * Button that must also announce that it is current. Without this prop, a component would have
   * to render its own `<button>` and repeat this recipe to add one attribute.
   */
  current?: boolean
  disabled?: boolean
  /**
   * Makes the button a disclosure's trigger. `aria-expanded` mirrors it. When it is omitted, the
   * button discloses nothing and the attribute does not render. It changes no styling: the icon
   * the caller passes shows the state.
   */
  expanded?: boolean
  /**
   * Leading icon. It is decorative, because the label names the action.
   */
  icon?: IconRole
  /**
   * Square (width = control height). `label` is still required as the accessible name.
   */
  iconOnly?: boolean
  /**
   * Required. Visible text, or the accessible name when `iconOnly`.
   */
  label: string
  loading?: boolean
  onClick?: (event: MouseEvent) => void
  /**
   * Makes the button a toggle. `aria-pressed` mirrors it and `data-state="on|off"` exposes it to
   * CSS. When it is omitted, the button is not a toggle and neither attribute renders. `loading`
   * takes precedence in `data-state`, so a busy toggle reports busy, while `aria-pressed` still
   * reports the toggle state.
   */
  pressed?: boolean
  size?: 'sm' | 'md' | 'lg'
  tone?: 'accent' | 'danger' | 'neutral'
  trailingIcon?: IconRole
  type?: 'button' | 'submit'
  variant?: 'solid' | 'soft' | 'outline' | 'ghost'
}
</script>

<script lang="ts">
let {
  'aria-controls': ariaControls,
  'aria-describedby': ariaDescribedbyOwn,
  'aria-label': ariaLabel,
  'aria-labelledby': ariaLabelledbyOwn,
  count,
  current = false,
  disabled = false,
  expanded,
  icon,
  iconOnly = false,
  label: labelOwn,
  loading = false,
  onClick: onClickOwn,
  pressed,
  size = 'md',
  tone = 'accent',
  trailingIcon,
  type = 'button',
  variant = 'solid',
}: ButtonProps = $props()
const joined = joinSlot(undefined, () => ({ disabled: disabled, label: labelOwn, size: size }))
const ariaDescribedby = $derived(
  joined.passed['aria-describedby'] === undefined
    ? ariaDescribedbyOwn
    : (joined.passed['aria-describedby'] as typeof ariaDescribedbyOwn),
)
const ariaLabelledby = $derived(
  joined.passed['aria-labelledby'] === undefined
    ? ariaLabelledbyOwn
    : (joined.passed['aria-labelledby'] as typeof ariaLabelledbyOwn),
)
const label = $derived(
  joined.passed['label'] === undefined ? labelOwn : (joined.passed['label'] as typeof labelOwn),
)
const onClick = $derived(chainHandlers(onClickOwn, joined.passed['onClick']))
let control = $state<HTMLElement | null>(null)
const dataState = $derived(
  loading ? 'loading' : pressed === undefined ? undefined : pressed ? 'on' : 'off',
)
const counted = $derived(count !== undefined && count.value > 0)
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const ran = agentMember({
    member: 'Button',
    element: () => control,
    state: () => ({
      disabled: disabled,
      loading: loading,
      pressed: pressed ?? null,
      expanded: expanded ?? null,
    }),
    actions: { press: () => agentPress(control) },
    destructive: () => Boolean(tone === 'danger'),
  })
  release1 = () => {
    ran()
  }
}
watchEffect(effect1)
onDestroy(() => release1?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }<button
    bind:this={control}
    class={styles.button}
    {type}
    {disabled}
    aria-busy={loading ? true : undefined}
    aria-current={current ? 'page' : undefined}
    aria-label={ariaLabel ?? (counted ? count?.label : iconOnly ? label : undefined)}
    aria-labelledby={ariaLabelledby}
    aria-describedby={ariaDescribedby}
    aria-pressed={pressed}
    aria-expanded={expanded}
    aria-controls={ariaControls}
    data-variant={variant}
    data-tone={tone}
    data-size={size}
    data-state={dataState}
    data-disabled={(disabled) ? '' : undefined}
    data-icon-only={(iconOnly) ? '' : undefined}
    data-member="button"
    onclick={(event) => { if (!loading) onClick?.(event) }}
    >{#if loading
      }<span class={styles.spinner}><Icon name="loading" {size} /></span
    >{:else if icon
      }<span class={styles.glyph}><Icon name={icon} {size} /></span
    >{/if
    }{#if !iconOnly}<span class={styles.label}>{label}</span>{/if
    }{#if trailingIcon !== undefined && !iconOnly
      }<span class={styles.glyph}><Icon name={trailingIcon} {size} /></span
    >{/if
    }{#if counted
      }<span class={styles.count} aria-hidden="true"
        ><Badge variant="solid" tone="accent" count={count?.value}
      /></span
    >{/if
  }</button
>{/if
}{@render joined.end?.()}
